<template><view class="page create-page"><view class="back" @tap="back">‹</view><view class="head"><text class="title">&#x65B0;&#x589E;&#x5546;&#x54C1;</text><text class="subtitle">&#x586B;&#x5199;&#x5546;&#x54C1;&#x4FE1;&#x606F;&#x540E;&#x786E;&#x8BA4;&#x4E0A;&#x67B6;&#x3002;</text></view><view class="form card"><text class="label">&#x5546;&#x54C1;&#x56FE;&#x7247;</text><view class="upload" @tap="chooseImage"><image v-if="image" :src="image" mode="aspectFill"/><view v-else><text class="upload-icon">&#x25A7;</text><text>&#x70B9;&#x51FB;&#x4E0A;&#x4F20;&#x56FE;&#x7247;</text></view></view><text class="label">&#x5546;&#x54C1;&#x540D;&#x79F0;</text><input class="input" placeholder="&#x8BF7;&#x8F93;&#x5165;&#x5546;&#x54C1;&#x540D;&#x79F0;" v-model="name"/><text class="label">&#x5546;&#x54C1;&#x78B3;&#x6807;&#x7B7E;</text><input class="input" placeholder="&#x4F8B;&#x5982;&#xFF1A;&#x53EF;&#x91CD;&#x590D;&#x4F7F;&#x7528; / &#x518D;&#x751F;&#x6750;&#x6599;" v-model="carbonLabel"/><view class="two"><view><text class="label">&#x6240;&#x9700;&#x78B3;&#x79EF;&#x5206;</text><input class="input" type="number" placeholder="0" v-model="points"/></view><view><text class="label">&#x521D;&#x59CB;&#x5E93;&#x5B58;</text><input class="input" type="number" placeholder="0" v-model="stock"/></view></view><text class="label">&#x9884;&#x8BA1;&#x51CF;&#x78B3;&#x503C;&#xFF08;kg CO&#x2082;/&#x4EF6;&#xFF09;</text><input class="input" type="digit" placeholder="&#x4F8B;&#x5982;&#xFF1A;0.8" v-model="carbonReduction"/><text class="label">&#x5546;&#x54C1;&#x63CF;&#x8FF0;</text><textarea class="textarea" placeholder="&#x8BF7;&#x8F93;&#x5165;&#x5546;&#x54C1;&#x8BE6;&#x7EC6;&#x63CF;&#x8FF0;..." v-model="description"/></view><view class="primary-btn submit" @tap="submit">&#x786E;&#x8BA4;&#x4E0A;&#x67B6;</view></view></template>
<script>
import {callCloud} from '../../common/cloud.js'
import {toast} from '../../common/mock.js'
export default {data(){return{image:'',imageFile:'',name:'',carbonLabel:'',carbonReduction:'',points:'',stock:'',description:''}},methods:{back(){uni.navigateBack()},chooseImage(){uni.chooseImage({count:1,sizeType:['compressed'],sourceType:['album','camera'],success:res=>{this.image=res.tempFilePaths[0];this.imageFile=res.tempFilePaths[0]},fail:()=>toast('\u672A\u80FD\u6253\u5F00\u76F8\u518C')})},async submit(){if(!this.imageFile||!this.name.trim()||!this.carbonLabel.trim()||this.points===''||this.stock===''||this.carbonReduction==='')return toast('\u8BF7\u5B8C\u5584\u56FE\u7247\u3001\u540D\u79F0\u3001\u78B3\u6807\u7B7E\u3001\u79EF\u5206\u3001\u5E93\u5B58\u548C\u9884\u8BA1\u51CF\u78B3\u503C');if(Number(this.points)<0||Number(this.stock)<0||Number(this.carbonReduction)<0)return toast('\u6570\u503C\u4E0D\u80FD\u5C0F\u4E8E0');try{const uploaded=await uniCloud.uploadFile({filePath:this.imageFile,cloudPath:'products/'+Date.now()+'.jpg'});await callCloud('product-create',{name:this.name.trim(),description:this.description,carbonLabel:this.carbonLabel.trim(),carbonReduction:Number(this.carbonReduction),points:Number(this.points),stock:Number(this.stock),image:uploaded.fileID,enterpriseId:uni.getStorageSync('user_session')?.id||'enterprise_demo'});toast('\u5546\u54C1\u5DF2\u4E0A\u67B6');setTimeout(()=>uni.navigateBack(),500)}catch(error){toast(error.message||'\u4E0A\u67B6\u5931\u8D25')}}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.create-page{padding-bottom:50rpx}.back{width:68rpx;height:68rpx;font-size:58rpx}.head{padding:28rpx 4rpx}.head .title{font-size:50rpx}.form{padding:28rpx}.label{display:block;margin:18rpx 0 12rpx;color:#53615f;font-size:24rpx}.upload{display:flex;align-items:center;justify-content:center;height:280rpx;border:4rpx dashed #b8cdbd;border-radius:22rpx;background:#f1f4f3;color:#53615f;text-align:center}.upload image{width:100%;height:100%;border-radius:18rpx}.upload-icon{display:block;margin-bottom:12rpx;font-size:54rpx;color:#006d37}.input{width:100%;height:92rpx;padding:0 24rpx;border-radius:20rpx;background:#f1f4f3;box-sizing:border-box}.two{display:flex;gap:18rpx}.two>view{flex:1}.textarea{width:100%;height:190rpx;padding:22rpx;border-radius:20rpx;background:#f1f4f3;box-sizing:border-box}.submit{margin-top:26rpx;height:100rpx;border-radius:52rpx}</style>
